-- transfer-category taxonomy (Task 20 section 22: multi-category routes)

-- tag every transfer_route: airport (origin is an airport), resort (destination not inhabited),
-- island (destination inhabited), hotel (destination inhabited AND has a real hotel/guesthouse accommodation)
select tr.id, (select id from nodes where node_type = 'category' and slug = 'airport')
from transfer_routes tr
join locations ol on ol.id = tr.origin_location_id
where ol.location_type = 'airport'
on conflict do nothing;
select tr.id, (select id from nodes where node_type = 'category' and slug = 'resort-transfer')
from transfer_routes tr
join locations dl on dl.id = tr.destination_location_id
where dl.is_inhabited = false
on conflict do nothing;
select tr.id, (select id from nodes where node_type = 'category' and slug = 'island-transfer')
from transfer_routes tr
join locations dl on dl.id = tr.destination_location_id
where dl.is_inhabited = true
on conflict do nothing;
select distinct tr.id, (select id from nodes where node_type = 'category' and slug = 'hotel-transfer')
from transfer_routes tr
join locations dl on dl.id = tr.destination_location_id
join node_locations nl on nl.location_id = dl.id
join accommodations acc on acc.id = nl.node_id
where dl.is_inhabited = true and acc.accommodation_type in ('hotel', 'guesthouse')
on conflict do nothing;

-- every route can take a private-transfer inquiry (Task 20 section 29), no fixed price
select id, 'inquiry', null, null, null from nodes where node_type = 'transfer_route'
on conflict (id) do nothing;

